import {
  DEVICE_INFO_CHAR_UUID,
  DEVICE_INFO_VECTORS,
  DEVICE_NAME_PREFIX,
  FLAG,
  MAX_VOLTAGE_MV,
  NAME_VECTORS,
  OFFSET,
  PACKET_SIZE,
  PROTOCOL_VERSION,
  SERVICE_UUID,
  TELEMETRY_CHAR_UUID,
  TELEMETRY_VECTORS,
} from '../src/index.js';

const BANNER =
  '// GENERATED by packages/protocol/scripts/generate.ts. DO NOT EDIT BY HAND.\n' +
  '// Source of truth: packages/protocol/src. Run `npm run gen:protocol` to refresh.\n';

function bytesToC(hex: string): string {
  return hex
    .split(' ')
    .map((b) => `0x${b}`)
    .join(', ');
}

function macToC(mac: string): string {
  return mac
    .split(':')
    .map((b) => `0x${b.toUpperCase()}`)
    .join(', ');
}

/** firmware/include/protocol_generated.h */
export function renderProtocolHeader(): string {
  return `${BANNER}#pragma once
#include <stdint.h>

#define FORCE_PROTO_VERSION ${PROTOCOL_VERSION}
#define FORCE_NAME_PREFIX "${DEVICE_NAME_PREFIX}"
#define FORCE_SERVICE_UUID "${SERVICE_UUID}"
#define FORCE_TELEMETRY_UUID "${TELEMETRY_CHAR_UUID}"
#define FORCE_DEVICE_INFO_UUID "${DEVICE_INFO_CHAR_UUID}"

#define FORCE_PACKET_SIZE ${PACKET_SIZE}
#define FORCE_OFF_SEQ ${OFFSET.seq}
#define FORCE_OFF_TIME ${OFFSET.deviceTimeMs}
#define FORCE_OFF_VOLTAGE ${OFFSET.voltageMv}
#define FORCE_OFF_CURRENT ${OFFSET.currentMa}
#define FORCE_OFF_POWER ${OFFSET.powerMw}
#define FORCE_OFF_FLAGS ${OFFSET.flags}

#define FORCE_FLAG_SENSOR_FAULT 0x${FLAG.SENSOR_FAULT.toString(16).padStart(2, '0')}
#define FORCE_FLAG_CURRENT_AT_LIMIT 0x${FLAG.CURRENT_AT_LIMIT.toString(16).padStart(2, '0')}

#define FORCE_MAX_VOLTAGE_MV ${MAX_VOLTAGE_MV}
`;
}

/** firmware/test/vectors_generated.h */
export function renderVectorsHeader(): string {
  const tel = TELEMETRY_VECTORS.map(
    (v) =>
      `  {"${v.name}", ${v.input.seq}u, ${v.input.deviceTimeMs}u, ${v.input.voltageMv}u, ${v.input.currentMa}, ${v.input.flags}u, ${v.expected.powerMw}u, {${bytesToC(v.hex)}}},`,
  ).join('\n');
  const info = DEVICE_INFO_VECTORS.map(
    (v) =>
      `  {"${v.info.id}", "${v.info.fw}", ${v.info.rateHz}, ${v.info.limitMa}, ${JSON.stringify(v.json)}},`,
  ).join('\n');
  const names = NAME_VECTORS.map((v) => `  {{${macToC(v.mac)}}, "${v.name}"},`).join('\n');
  return `${BANNER}#pragma once
#include <stdint.h>

struct TelemetryVector {
  const char* name;
  uint16_t seq;
  uint32_t deviceTimeMs;
  uint16_t voltageMv;
  int16_t currentMa;
  uint8_t flags;
  uint32_t expectedPowerMw;
  uint8_t bytes[15];
};

static const TelemetryVector TELEMETRY_VECTORS[] = {
${tel}
};
static const int TELEMETRY_VECTOR_COUNT = ${TELEMETRY_VECTORS.length};

struct DeviceInfoVector {
  const char* id;
  const char* fw;
  int rateHz;
  int limitMa;
  const char* json;
};

static const DeviceInfoVector DEVICE_INFO_VECTORS[] = {
${info}
};
static const int DEVICE_INFO_VECTOR_COUNT = ${DEVICE_INFO_VECTORS.length};

struct NameVector {
  uint8_t mac[6];
  const char* name;
};

static const NameVector NAME_VECTORS[] = {
${names}
};
static const int NAME_VECTOR_COUNT = ${NAME_VECTORS.length};
`;
}

function hexBytes(hex: string, from: number, len: number): string {
  return hex
    .split(' ')
    .slice(from, from + len)
    .join(' ');
}

/** docs/PACKET_EXAMPLES.md */
export function renderPacketExamples(): string {
  const vectors = TELEMETRY_VECTORS.map((v) => {
    const f = v.expected;
    return `### ${v.name}

${v.description}

\`\`\`
${v.hex}
\`\`\`

| Field | Bytes | Hex (as sent) | Value |
| --- | --- | --- | --- |
| seq | 0-1 | ${hexBytes(v.hex, OFFSET.seq, 2)} | ${f.seq} |
| device time | 2-5 | ${hexBytes(v.hex, OFFSET.deviceTimeMs, 4)} | ${f.deviceTimeMs} ms |
| voltage | 6-7 | ${hexBytes(v.hex, OFFSET.voltageMv, 2)} | ${f.voltageMv} mV |
| current | 8-9 | ${hexBytes(v.hex, OFFSET.currentMa, 2)} | ${f.currentMa} mA |
| power | 10-13 | ${hexBytes(v.hex, OFFSET.powerMw, 4)} | ${f.powerMw} mW |
| flags | 14 | ${hexBytes(v.hex, OFFSET.flags, 1)} | 0b${f.flags.toString(2).padStart(8, '0')} |
`;
  }).join('\n');

  const info = DEVICE_INFO_VECTORS.map((v) => `- \`${v.json}\``).join('\n');
  const names = NAME_VECTORS.map((v) => `| \`${v.mac}\` | \`${v.name}\` |`).join('\n');

  return `# Packet examples

<!-- GENERATED by packages/protocol/scripts/generate.ts from packages/protocol/src/vectors.ts. Do not edit by hand. -->

These worked examples are the single source for the cross-language agreement test:
the firmware host tests (\`firmware/test\`) and the TypeScript tests (\`packages/protocol\`,
\`packages/engine\`) assert **byte for byte** that they produce and read exactly these packets.
The hex was calculated by hand, independently of the packer.

## Protocol

| Item | Value |
| --- | --- |
| Advertised name | \`${DEVICE_NAME_PREFIX}\` + last four hex characters of the BLE MAC, upper case |
| Service | \`${SERVICE_UUID}\` |
| Telemetry (NOTIFY) | \`${TELEMETRY_CHAR_UUID}\` |
| Device Info (READ) | \`${DEVICE_INFO_CHAR_UUID}\` |
| Packet | ${PACKET_SIZE} bytes, little-endian, one sample per notification |

| Offset | Size | Field | Type | Unit |
| --- | --- | --- | --- | --- |
| 0 | 2 | seq | uint16 | +1 per sample, wraps at 65536 |
| 2 | 4 | device time | uint32 | ms since boot |
| 6 | 2 | voltage | uint16 | mV |
| 8 | 2 | current | int16 | mA (signed) |
| 10 | 4 | power | uint32 | mW, 0 if current is negative; round half up of mV x mA / 1000 |
| 14 | 1 | flags | uint8 | bit0 sensor fault, bit1 current at limit |

## Telemetry packets

${vectors}
## Device Info (UTF-8 JSON, fixed key order, no whitespace)

${info}

## Name from MAC

| BLE MAC | Advertised name |
| --- | --- |
${names}
`;
}

/** Every generated artefact: path relative to the repo root, and its renderer. */
export const GENERATED: ReadonlyArray<{ path: string; render: () => string }> = [
  { path: 'firmware/include/protocol_generated.h', render: renderProtocolHeader },
  { path: 'firmware/test/vectors_generated.h', render: renderVectorsHeader },
  { path: 'docs/PACKET_EXAMPLES.md', render: renderPacketExamples },
];
